// Construye el request para el API de Anthropic (Claude vision + structured outputs)
const incoming = $input.first().json;
const body = incoming.body || incoming;
const photos = (body.photos || []).slice(0, 4);
const catalog = (body.catalog || []).slice(0, 400);
const fixture = body.fixture || {};

if (!photos.length) {
  throw new Error('El payload no trae fotos');
}

const catalogText = catalog
  .map((p) => `${p.sku} | ${p.name} | ${p.brand} | ${p.category} | Q${p.price}`)
  .join('\n');

const content = [];
for (const photo of photos) {
  const match = String(photo.dataUrl || '').match(/^data:(image\/[a-z.+-]+);base64,(.+)$/s);
  if (!match) continue;
  content.push({ type: 'text', text: `Foto del modulo "${photo.id}": ${photo.label}` });
  content.push({ type: 'image', source: { type: 'base64', media_type: match[1], data: match[2] } });
}

const moduleIds = photos.map((p) => p.id).join(', ');

content.push({
  type: 'text',
  text: [
    'Eres un agente de reconocimiento de planogramas para Cemaco (retail de hogar en Guatemala).',
    `Contexto: tienda ${body.store}, categoria ${body.category}, mueble "${fixture.name}" de ${fixture.width}cm de ancho, ${fixture.levels} niveles y ${fixture.depth}cm de profundidad.`,
    '',
    'Analiza las fotos del mueble y construye el realogram: por cada nivel visible (de arriba hacia abajo), lista los productos de izquierda a derecha con sus facings (repeticiones contiguas del mismo producto).',
    'Intenta hacer match de cada producto contra el catalogo usando marca, texto visible del empaque, forma y color. La etiqueta de precio solo apoya cuando se alcanza a leer.',
    '',
    'Reglas:',
    '- Usa el sku EXACTO del catalogo (formato "sku ########") solo cuando el match sea razonable; si no hay match, deja sku como cadena vacia y describe el producto en detectedName.',
    '- confidence de 0 a 100, honesto: 80+ match claro, 50-79 probable, menos de 50 dudoso.',
    '- NO inventes productos que no se ven en la foto. Si un nivel esta vacio o no se distingue, no lo incluyas.',
    `- moduleId de cada item: el id de la foto donde aparece (valores validos: ${moduleIds}).`,
    '- alternatives: hasta 3 candidatos alternos del catalogo por item, con su confidence.',
    '- reason: una frase corta con el motivo del match (ej. "marca Truper legible en empaque").',
    '- fixtureSummary: una frase describiendo el mueble y su estado general (denso, semivacio, etc).',
    '',
    'Catalogo disponible (sku | nombre | marca | categoria | precio):',
    catalogText,
  ].join('\n'),
});

const itemSchema = {
  type: 'object',
  properties: {
    sku: { type: 'string', description: 'sku exacto del catalogo, o cadena vacia si no hay match' },
    detectedName: { type: 'string' },
    facings: { type: 'integer' },
    confidence: { type: 'integer' },
    moduleId: { type: 'string' },
    reason: { type: 'string' },
    alternatives: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          sku: { type: 'string' },
          name: { type: 'string' },
          confidence: { type: 'integer' }
        },
        required: ['sku', 'name', 'confidence'],
        additionalProperties: false
      }
    }
  },
  required: ['sku', 'detectedName', 'facings', 'confidence', 'moduleId', 'reason', 'alternatives'],
  additionalProperties: false
};

const schema = {
  type: 'object',
  properties: {
    fixtureSummary: { type: 'string' },
    rows: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          confidence: { type: 'integer' },
          items: { type: 'array', items: itemSchema }
        },
        required: ['name', 'confidence', 'items'],
        additionalProperties: false
      }
    }
  },
  required: ['fixtureSummary', 'rows'],
  additionalProperties: false
};

return [{
  json: {
    anthropicBody: {
      model: 'claude-opus-4-8',
      max_tokens: 16000,
      thinking: { type: 'adaptive' },
      output_config: { format: { type: 'json_schema', schema } },
      messages: [{ role: 'user', content }]
    }
  }
}];

// Convierte la respuesta de Claude al formato que espera la app
const response = $input.first().json;

if (response.stop_reason === 'refusal') {
  return [{ json: { rows: [], fixtureSummary: '', error: 'El modelo declino la solicitud' } }];
}

const text = (response.content || [])
  .filter((block) => block.type === 'text')
  .map((block) => block.text)
  .join('');

let parsed = { rows: [], fixtureSummary: '' };
try {
  parsed = JSON.parse(text);
} catch (error) {
  return [{ json: { rows: [], fixtureSummary: '', error: 'Respuesta no parseable', raw: text.slice(0, 500) } }];
}

const rows = (parsed.rows || []).map((row) => ({
  name: row.name,
  confidence: row.confidence,
  items: (row.items || []).map((item) => ({
    sku: item.sku && item.sku.trim() ? item.sku.trim() : null,
    detectedName: item.detectedName || '',
    facings: item.facings || 1,
    confidence: item.confidence || 0,
    moduleId: item.moduleId || 'front',
    reason: item.reason || '',
    alternatives: item.alternatives || []
  }))
}));

return [{ json: { rows, fixtureSummary: parsed.fixtureSummary || '' } }];
